using FamilyVeda.Application.Common;
using FamilyVeda.Application.Triage;
using FamilyVeda.Domain.Clinical;
using FamilyVeda.Domain.Common;
using FamilyVeda.Domain.Identity;
using FamilyVeda.Domain.Triage;
using FamilyVeda.Infrastructure.Persistence;
using FamilyVeda.Infrastructure.Triage;
using FluentAssertions;
using Microsoft.EntityFrameworkCore;

namespace FamilyVeda.UnitTests;

public sealed class TriageReviewReasonsTests
{
    [Fact]
    public async Task GetCaseReview_WithActiveGrant_ReturnsTheExactSubmittedEpisode()
    {
        await using var db = NewDb();
        var fixture = await SeedAsync(db);
        await AddGrantAsync(db, fixture, GrantState.Active);
        var service = CreateService(db, fixture.DoctorUser.Id, UserType.Doctor);

        var review = await service.GetCaseReviewAsync(fixture.LinkedCase.Id, CancellationToken.None);

        review.SubmittedEpisode.Should().NotBeNull();
        review.SubmittedEpisode!.Id.Should().Be(fixture.LinkedEpisode.Id);
        review.SubmittedEpisode.MemberId.Should().Be(fixture.LinkedMember.Id);
        review.SubmittedEpisode.Symptoms.Should().Equal("synthetic_persistent_cough", "synthetic_fatigue");
        review.SubmittedEpisode.DurationDays.Should().Be(4);
        review.SubmittedEpisode.Severity.Should().Be(3);
        review.SubmittedEpisode.Notes.Should().Be("Synthetic linked episode note.");
        review.SubmittedEpisode.Id.Should().NotBe(fixture.OtherMemberEpisode.Id);
    }

    [Fact]
    public async Task GetCaseReview_WithMismatchedEpisodeMember_DoesNotExposeEpisode()
    {
        await using var db = NewDb();
        var fixture = await SeedAsync(db);
        await AddGrantAsync(db, fixture, GrantState.Active);
        fixture.LinkedCase.Episode = fixture.OtherMemberEpisode;
        fixture.LinkedCase.EpisodeId = fixture.OtherMemberEpisode.Id;
        await db.SaveChangesAsync();
        var service = CreateService(db, fixture.DoctorUser.Id, UserType.Doctor);

        var review = await service.GetCaseReviewAsync(fixture.LinkedCase.Id, CancellationToken.None);

        review.SubmittedEpisode.Should().BeNull();
    }

    [Fact]
    public async Task GetCaseReview_GrantForOneCase_CannotReadAnotherMembersEpisode()
    {
        await using var db = NewDb();
        var fixture = await SeedAsync(db);
        await AddGrantAsync(db, fixture, GrantState.Active);
        var service = CreateService(db, fixture.DoctorUser.Id, UserType.Doctor);

        var act = () => service.GetCaseReviewAsync(fixture.OtherMemberCase.Id, CancellationToken.None);

        await act.Should().ThrowAsync<NotFoundException>();
    }

    [Theory]
    [InlineData(GrantState.None)]
    [InlineData(GrantState.Expired)]
    [InlineData(GrantState.Revoked)]
    public async Task GetCaseReview_WithoutAnActiveGrant_IsDenied(GrantState grantState)
    {
        await using var db = NewDb();
        var fixture = await SeedAsync(db);
        await AddGrantAsync(db, fixture, grantState);
        var service = CreateService(db, fixture.DoctorUser.Id, UserType.Doctor);

        var act = () => service.GetCaseReviewAsync(fixture.LinkedCase.Id, CancellationToken.None);

        await act.Should().ThrowAsync<NotFoundException>();
    }

    [Fact]
    public async Task GetCaseReview_ForFamilyUser_IsDenied()
    {
        await using var db = NewDb();
        var fixture = await SeedAsync(db);
        var service = CreateService(db, fixture.FamilyUser.Id, UserType.FamilyUser);

        var act = () => service.GetCaseReviewAsync(fixture.LinkedCase.Id, CancellationToken.None);

        await act.Should().ThrowAsync<NotFoundException>();
    }

    private static AppDbContext NewDb() =>
        new(new DbContextOptionsBuilder<AppDbContext>()
            .UseInMemoryDatabase(Guid.NewGuid().ToString())
            .Options);

    private static TriageService CreateService(AppDbContext db, Guid userId, UserType userType) =>
        new(db, new StubCurrentUser(userId, userType), new StubWorkQueue());

    private static async Task<Fixture> SeedAsync(AppDbContext db)
    {
        var familyUser = new UserAccount
        {
            Email = "synthetic-review-family@example.invalid",
            PasswordHash = "synthetic-hash",
            DisplayName = "Synthetic Review Family",
            UserType = UserType.FamilyUser
        };
        var otherFamilyUser = new UserAccount
        {
            Email = "synthetic-review-other@example.invalid",
            PasswordHash = "synthetic-hash",
            DisplayName = "Synthetic Other Family",
            UserType = UserType.FamilyUser
        };
        var doctorUser = new UserAccount
        {
            Email = "synthetic-review-doctor@example.invalid",
            PasswordHash = "synthetic-hash",
            DisplayName = "Synthetic Review Doctor",
            UserType = UserType.Doctor
        };
        var family = new Family { Name = "Synthetic Review Family", CreatedByUser = familyUser };
        var otherFamily = new Family { Name = "Synthetic Other Family", CreatedByUser = otherFamilyUser };
        var linkedMember = new Member
        {
            Family = family,
            User = familyUser,
            DisplayName = "Synthetic Linked Member",
            DateOfBirth = new DateOnly(1990, 1, 1),
            Role = FamilyRole.Head
        };
        var otherMember = new Member
        {
            Family = otherFamily,
            User = otherFamilyUser,
            DisplayName = "Synthetic Other Member",
            DateOfBirth = new DateOnly(1992, 2, 2),
            Role = FamilyRole.Head
        };
        var doctor = new Doctor
        {
            User = doctorUser,
            RegistrationNumberHash = "synthetic-registration-hash",
            RegistrationNumberLastFour = "0001",
            VerificationStatus = VerificationStatus.Verified
        };
        var linkedEpisode = new Episode
        {
            Member = linkedMember,
            SymptomsJson = "[\"synthetic_persistent_cough\",\"synthetic_fatigue\"]",
            DurationDays = 4,
            Severity = 3,
            Notes = "Synthetic linked episode note."
        };
        var otherMemberEpisode = new Episode
        {
            Member = otherMember,
            SymptomsJson = "[\"synthetic_unrelated_symptom\"]",
            DurationDays = 9,
            Severity = 1,
            Notes = "Synthetic unrelated episode note."
        };
        var linkedCase = new TriageCase
        {
            Episode = linkedEpisode,
            Member = linkedMember,
            Status = TriageStatus.PendingDoctorReview,
            Priority = TriagePriority.Priority
        };
        var otherMemberCase = new TriageCase
        {
            Episode = otherMemberEpisode,
            Member = otherMember,
            Status = TriageStatus.PendingDoctorReview,
            Priority = TriagePriority.Routine
        };

        db.AddRange(
            familyUser,
            otherFamilyUser,
            doctorUser,
            family,
            otherFamily,
            linkedMember,
            otherMember,
            doctor,
            linkedEpisode,
            otherMemberEpisode,
            linkedCase,
            otherMemberCase);
        await db.SaveChangesAsync();

        return new Fixture(
            familyUser,
            doctorUser,
            doctor,
            linkedMember,
            linkedEpisode,
            linkedCase,
            otherMemberEpisode,
            otherMemberCase);
    }

    private static async Task AddGrantAsync(AppDbContext db, Fixture fixture, GrantState grantState)
    {
        if (grantState == GrantState.None)
        {
            return;
        }

        var now = DateTimeOffset.UtcNow;
        db.CaseAccessGrants.Add(new CaseAccessGrant
        {
            TriageCase = fixture.LinkedCase,
            Doctor = fixture.Doctor,
            ExpiresAt = grantState == GrantState.Expired ? now.AddMinutes(-1) : now.AddHours(1),
            RevokedAt = grantState == GrantState.Revoked ? now.AddMinutes(-1) : null,
            Reason = "SYNTHETIC_REVIEW_TEST"
        });
        await db.SaveChangesAsync();
    }

    private sealed record Fixture(
        UserAccount FamilyUser,
        UserAccount DoctorUser,
        Doctor Doctor,
        Member LinkedMember,
        Episode LinkedEpisode,
        TriageCase LinkedCase,
        Episode OtherMemberEpisode,
        TriageCase OtherMemberCase);

    private sealed class StubCurrentUser(Guid userId, UserType userType) : ICurrentUser
    {
        public bool IsAuthenticated => true;
        public Guid UserId => userId;
        public UserType UserType => userType;
    }

    private sealed class StubWorkQueue : ITriageWorkQueue
    {
        public ValueTask QueueAsync(Guid caseId, CancellationToken cancellationToken) => ValueTask.CompletedTask;
        public ValueTask<Guid> DequeueAsync(CancellationToken cancellationToken) => ValueTask.FromResult(Guid.Empty);
    }

    public enum GrantState
    {
        None,
        Active,
        Expired,
        Revoked
    }
}
